<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require __DIR__.'/src/App.php';
try{$cmd=$argv[1]??'report';if(in_array($cmd,['start','stop'],true)){$c=PatternService::config();$c['enabled']=$cmd==='start';$r=PatternService::save($c);}
 elseif($cmd==='tick')$r=PatternService::tick();elseif($cmd==='report')$r=PatternService::view();elseif($cmd==='run'){$lock=fopen(__DIR__.'/data/pattern-collector.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new RuntimeException('Pattern collector already running');file_put_contents(__DIR__.'/data/pattern-collector.pid',(string)getmypid());try{while(PatternService::config()['enabled']){$r=PatternService::tick();echo encode(['at'=>gmdate('c'),'status'=>$r['status']??'CHECKED','signals'=>count($r['signals']??[])])."\n";sleep(5);}}finally{flock($lock,LOCK_UN);fclose($lock);@unlink(__DIR__.'/data/pattern-collector.pid');}exit;}else throw new RuntimeException('Use start, stop, tick, run or report');$json=json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(isset($argv[2]))file_put_contents($argv[2],$json."\n");else echo $json."\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
